/* ── Contact Form Handler ── */
(function(){
  var form=document.getElementById('contactForm');
  var btn=document.getElementById('contactSubmitBtn');
  var API_URL='/wp-json/zafira/v1/solicitud';

  function sanitize(str){return str.replace(/[<>]/g,'').trim();}
  function isValidEmail(e){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);}

  function showError(id,show){
    var el=document.getElementById(id);
    var input=el.previousElementSibling;
    if(show){el.classList.add('show');input.classList.add('error');}
    else{el.classList.remove('show');input.classList.remove('error');}
  }

  form.addEventListener('submit',function(e){
    e.preventDefault();
    var name=sanitize(document.getElementById('contactName').value);
    var email=sanitize(document.getElementById('contactEmail').value);
    var message=sanitize(document.getElementById('contactMessage').value);
    var valid=true;

    showError('nameError',!name); if(!name)valid=false;
    showError('emailError',!isValidEmail(email)); if(!isValidEmail(email))valid=false;
    showError('messageError',!message); if(!message)valid=false;
    if(!valid)return;

    btn.textContent=window.zafiraGetLang&&window.zafiraGetLang()==='es'?'Enviando...':'Sending...';
    btn.disabled=true;

    fetch(API_URL,{
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({formType:'contact',Nombre:name,email:email,message:message})
